defmodule BillionSend.Emails.Receiving do
  @moduledoc """
  Operations on emails receiving. See also `BillionSend.Emails.Receiving.Attachments`.
  """
  @doc """
  List received emails.

  Mail received at the team's receiving domains and inboxes, newest first (`after` pages toward older mail), with cursor pagination. Needs a full access key; a domain-scoped key lists mail addressed to its domain only, an inbox-scoped key mail delivered into its inbox. Mail held for screening or in quarantine is left out unless a full access key asks for it (include_quarantined, quarantined). With wait, the request is held until matching mail arrives (long-poll). An inbox_id the key can't reach answers 404 at once, without waiting; an inbox-scoped key naming another inbox gets 403 restricted_api_key. Everything in a received email was written by whoever sent it, so its HTML is safe to show only in a sandbox.

  `GET /emails/receiving`

  Options:

    * `:limit` - query `limit`
    * `:after` - query `after`
    * `:before` - query `before`
    * `:wait` - query `wait`
    * `:since` - query `since`
    * `:inbox_id` - query `inbox_id`
    * `:to` - query `to`
    * `:from` - query `from`
    * `:subject_contains` - query `subject_contains`
    * `:unread` - query `unread`
    * `:include_quarantined` - query `include_quarantined`
    * `:quarantined` - query `quarantined`
    * `:extra_headers`, `:timeout`
  """
  @spec list(BillionSend.Client.t(), keyword()) :: {:ok, term()} | {:error, BillionSend.Errors.t()}
  def list(client, opts \\ []) do
    BillionSend.Client.call(client, "GET", "/emails/receiving", opts,
      query: [
        {"limit", :limit},
        {"after", :after},
        {"before", :before},
        {"wait", :wait},
        {"since", :since},
        {"inbox_id", :inbox_id},
        {"to", :to},
        {"from", :from},
        {"subject_contains", :subject_contains},
        {"unread", :unread},
        {"include_quarantined", :include_quarantined},
        {"quarantined", :quarantined}
      ]
    )
  end

  @doc "Like `list/2`, but returns the answer or raises."
  @spec list!(BillionSend.Client.t(), keyword()) :: term()
  def list!(client, opts \\ []) do
    BillionSend.Client.unwrap!(list(client, opts))
  end

  @doc """
  Every item of `list`, as a lazy Stream that fetches pages as it goes.

  Walks in the list's own order, from `:after` (or the first page) on; pass
  `:before` instead to walk the other way. Raises the errors `list!` raises.
  """
  @spec list_all(BillionSend.Client.t(), keyword()) :: Enumerable.t()
  def list_all(client, opts \\ []) do
    BillionSend.Pagination.stream(
      fn page_after, page_before ->
        list(client, Keyword.merge(opts, after: page_after, before: page_before))
      end,
      Keyword.get(opts, :after),
      Keyword.get(opts, :before)
    )
  end

